@@ -0,0 +1,55 @@
+'use client';
+
+import { Bell, BellOff, Loader2 } from 'lucide-react';
+import { cn } from '@/lib/utils';
+import { usePushNotifications } from '@/hooks/usePushNotifications';
+
+interface PushNotificationButtonProps {
+  className?: string;
+  isMobile?: boolean;
+}
+
+export function PushNotificationButton({
+  className,
+  isMobile = false,
+}: PushNotificationButtonProps) {
+  const { isSupported, isSubscribed, isLoading, subscribe, unsubscribe } = usePushNotifications();
+
+  // Don't show if not supported
+  if (!isSupported) {
+    return null;
+  }
+
+  const handleClick = async () => {
+    if (isSubscribed) {
+      await unsubscribe();
+    } else {
+      await subscribe();
+    }
+  };
+
+  const iconClass = isMobile ? 'h-5 w-5' : 'h-4 w-4';
+
+  return (
+    <button
+      onClick={handleClick}
+      disabled={isLoading}
+      className={cn(
+        'rounded-lg text-white/40 transition-colors hover:bg-white/5 hover:text-white',
+        'touch-manipulation disabled:opacity-50',
+        isMobile ? 'min-h-[44px] min-w-[44px] p-2.5' : 'p-2',
+        isSubscribed && 'text-orange-400 hover:text-orange-300',
+        className
+      )}
+      title={isSubscribed ? 'Disable notifications' : 'Enable notifications'}
+    >
+      {isLoading ? (
+        <Loader2 className={cn(iconClass, 'animate-spin')} />
+      ) : isSubscribed ? (
+        <Bell className={iconClass} />
+      ) : (
+        <BellOff className={iconClass} />
+      )}
+    </button>
+  );
+}
diff --git a/claude-remote-control/apps/web/src/hooks/usePushNotifications.ts b/claude-remote-control/apps/web/src/hooks/usePushNotifications.ts
new file mode 100644
index 0000000..49d7720
--- /dev/null
+++ b/claude-remote-control/apps/web/src/hooks/usePushNotifications.ts
@@ -0,0 +1,196 @@
+'use client';
+
+import { useState, useEffect, useCallback } from 'react';
+
+interface PushNotificationState {
+  isSupported: boolean;
+  isSubscribed: boolean;
+  permission: NotificationPermission | 'default';
+  isLoading: boolean;
+  error: string | null;
+}
+
+/**
+ * Convert a base64 string to Uint8Array for applicationServerKey
+ */
+function urlBase64ToUint8Array(base64String: string): Uint8Array<ArrayBuffer> {
+  const padding = '='.repeat((4 - (base64String.length % 4)) % 4);
+  const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
+  const rawData = window.atob(base64);
+  const buffer = new ArrayBuffer(rawData.length);
+  const outputArray = new Uint8Array(buffer);
+  for (let i = 0; i < rawData.length; ++i) {
+    outputArray[i] = rawData.charCodeAt(i);
+  }
+  return outputArray;
+}
+
+export function usePushNotifications() {
+  const [state, setState] = useState<PushNotificationState>({
+    isSupported: false,
+    isSubscribed: false,
+    permission: 'default',
+    isLoading: true,
+    error: null,
+  });
+
+  // Check initial state
+  useEffect(() => {
+    const checkSupport = async () => {
+      const isSupported =
+        'serviceWorker' in navigator && 'PushManager' in window && 'Notification' in window;
+
+      if (!isSupported) {
+        setState((s) => ({ ...s, isSupported: false, isLoading: false }));
+        return;
+      }
+
+      const permission = Notification.permission;
+
+      // Check if already subscribed
+      try {
+        const registration = await navigator.serviceWorker.ready;
+        const subscription = await registration.pushManager.getSubscription();
+        setState({
+          isSupported: true,
+          isSubscribed: !!subscription,
+          permission,
+          isLoading: false,
+          error: null,
+        });
+      } catch (error) {
+        console.error('[Push] Error checking subscription:', error);
+        setState((s) => ({
+          ...s,
+          isSupported: true,
+          permission,
+          isLoading: false,
+          error: 'Failed to check subscription status',
+        }));
+      }
+    };
+
+    checkSupport();
+  }, []);
+
+  /**
+   * Subscribe to push notifications
+   */
+  const subscribe = useCallback(async () => {
+    if (!state.isSupported) {
+      setState((s) => ({ ...s, error: 'Push notifications not supported' }));
+      return false;
+    }
+
+    setState((s) => ({ ...s, isLoading: true, error: null }));
+
+    try {
+      // Request notification permission
+      const permission = await Notification.requestPermission();
+      if (permission !== 'granted') {
+        setState((s) => ({
+          ...s,
+          permission,
+          isLoading: false,
+          error: 'Notification permission denied',
+        }));
+        return false;
+      }
+
+      // Get VAPID public key
+      const vapidResponse = await fetch('/api/push/vapid-key');
+      if (!vapidResponse.ok) {
+        throw new Error('Failed to get VAPID key');
+      }
+      const { publicKey } = await vapidResponse.json();
+
+      // Subscribe to push
+      const registration = await navigator.serviceWorker.ready;
+      const subscription = await registration.pushManager.subscribe({
+        userVisibleOnly: true,
+        applicationServerKey: urlBase64ToUint8Array(publicKey),
+      });
+
+      // Send subscription to server
+      const response = await fetch('/api/push/subscribe', {
+        method: 'POST',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({
+          subscription: subscription.toJSON(),
+          userAgent: navigator.userAgent,
+        }),
+      });
+
+      if (!response.ok) {
+        throw new Error('Failed to save subscription');
+      }
+
+      setState({
+        isSupported: true,
+        isSubscribed: true,
+        permission: 'granted',
+        isLoading: false,
+        error: null,
+      });
+
+      console.warn('[Push] Successfully subscribed');
+      return true;
+    } catch (error) {
+      console.error('[Push] Subscription error:', error);
+      setState((s) => ({
+        ...s,
+        isLoading: false,
+        error: error instanceof Error ? error.message : 'Failed to subscribe',
+      }));
+      return false;
+    }
+  }, [state.isSupported]);
+
+  /**
+   * Unsubscribe from push notifications
+   */
+  const unsubscribe = useCallback(async () => {
+    setState((s) => ({ ...s, isLoading: true, error: null }));
+
+    try {
+      const registration = await navigator.serviceWorker.ready;
+      const subscription = await registration.pushManager.getSubscription();
+
+      if (subscription) {
+        // Unsubscribe from push manager
+        await subscription.unsubscribe();
+
+        // Remove from server
+        await fetch('/api/push/subscribe', {
+          method: 'DELETE',
+          headers: { 'Content-Type': 'application/json' },
+          body: JSON.stringify({ endpoint: subscription.endpoint }),
+        });
+      }
+
+      setState((s) => ({
+        ...s,
+        isSubscribed: false,
+        isLoading: false,
+        error: null,
+      }));
+
+      console.warn('[Push] Successfully unsubscribed');
+      return true;
+    } catch (error) {
+      console.error('[Push] Unsubscribe error:', error);
+      setState((s) => ({
+        ...s,
+        isLoading: false,
+        error: error instanceof Error ? error.message : 'Failed to unsubscribe',
+      }));
+      return false;
+    }
+  }, []);
+
+  return {
+    ...state,
+    subscribe,
+    unsubscribe,
+  };
+}

